async function openDocsView() {
  const d = os.get('extension.views.header-view.ui-data');
  d.docs_open = !os.mounted('extension.views.docs-view');
  if (d.docs_open) await ctx.call('extension.functions.render', { view_path: 'extension.views.docs-view' });
  else await ctx.call('extension.functions.unmount', { view_path: 'extension.views.docs-view' });
  await ctx.call('extension.functions.render', { view_path: 'extension.views.header-view' });
}

