async function openDoc({ name }) {
  const d = os.get('extension.views.docs-view.ui-data'), folder = os.get('agents.agent-oss.files.docs') || {};
  if (!(name in folder)) throw new Error('No doc ' + name);
  d.selected = name;
  d.content = folder[name];
  // Draw the view again from ui-data.
  ctx.root.innerHTML = os.template(os.get('extension.views.docs-view.html'), d);
  os.bind(ctx.root, 'extension.views.docs-view');
}

